def rle_encode(s):
    """Compress runs of characters as 'char+count'."""
    if not s:
        return ""

    result = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    result.append(f"{current_char}{count}")

    return ''.join(result)


def rle_decode(s):
    """Reverse rle_encode: 'a3b1c3' -> 'aaabccc'."""
    if not s:
        return ""

    result = []
    i = 0

    while i < len(s):
        char = s[i]
        count = int(s[i+1])
        result.append(char * count)
        i += 2

    return ''.join(result)
