def rle_encode(s: str) -> str:
    """Encodes the input string using run-length encoding."""
    if not s:
        return ""
    encoded = []
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            encoded.append(f"{current_char}{count}")
            current_char = char
            count = 1
    encoded.append(f"{current_char}{count}")
    return "".join(encoded)


def rle_decode(s: str) -> str:
    """Decodes a run-length encoded string back to the original."""
    if not s:
        return ""
    decoded = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        count = int(s[i])
        i += 1
        decoded.append(char * count)
    return "".join(decoded)


# Example usage:
if __name__ == "__main__":
    print(rle_encode('aaabccc'))          # 'a3b1c3'
    print(rle_decode('a3b1c3'))          # 'aaabccc'
